const user = await prisma.user.findUnique({
  where: { id: userId },
  include: { posts: true }
});

await prisma.post.create({
  data: {
    title: 'New Post',
    author: { connect: { id: user.id } }
  }
});

await prisma.$transaction([
  prisma.user.delete({ where: { id } }),
  prisma.post.deleteMany({ where: { userId: id } })
]);
